    /** Not finally proven (nog niet definitief bewezen). */
    case NotFinallyProven = '901';
    /** Deleted to abroad (Afgeschreven naar het buitenland). */
    case DeletedToAbroad = '992';
    /** At sea (Op zee). */
    case AtSea = '995';
    /** Undetermined (Onbepaald), ISO XX. */
    case Undetermined = '999';
}
